use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use thiserror::Error;

pub const PROBE_VERSION_V0: &str = "mutation-probe.oxideloop.dev/v0";

/// Generate the checked-in probe schema with deterministic object-key order.
///
/// Workspace feature unification can make `serde_json::Map` preserve insertion
/// order, so serializing Schemars' internal maps directly is not reproducible.
///
/// # Panics
///
/// Panics only if a schema generated by Schemars cannot be represented or
/// serialized as JSON, which indicates an internal dependency invariant broke.
#[must_use]
pub fn generated_probe_schema() -> String {
    let schema = schemars::schema_for!(ProbeCaseV0);
    let value = serde_json::to_value(schema).expect("a generated schema is JSON serializable");
    let mut output = serde_json::to_string_pretty(&sort_json(value))
        .expect("a generated schema is JSON serializable");
    output.push('\n');
    output
}

fn sort_json(value: Value) -> Value {
    match value {
        Value::Object(object) => {
            let mut entries = object.into_iter().collect::<Vec<_>>();
            entries.sort_by(|left, right| left.0.cmp(&right.0));
            Value::Object(
                entries
                    .into_iter()
                    .map(|(key, value)| (key, sort_json(value)))
                    .collect(),
            )
        }
        Value::Array(values) => Value::Array(values.into_iter().map(sort_json).collect()),
        scalar => scalar,
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(
    tag = "class",
    rename_all = "camelCase",
    rename_all_fields = "camelCase",
    deny_unknown_fields
)]
pub enum BackendQualification {
    BuiltInTested {
        kubernetes_minor: String,
        gvr: String,
    },
    NativeStructuralCrd {
        kubernetes_minor: String,
        gvr: String,
        compatibility_manifest: String,
    },
    Unsupported {
        reason: String,
    },
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ObjectIdentity {
    pub uid: String,
    pub resource_version: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(
    tag = "state",
    rename_all = "camelCase",
    rename_all_fields = "camelCase",
    deny_unknown_fields
)]
pub enum Observation {
    Absent,
    Existing { identity: ObjectIdentity },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(
    tag = "operation",
    rename_all = "camelCase",
    rename_all_fields = "camelCase",
    deny_unknown_fields
)]
pub enum MutationIntent {
    Create {
        observation: Observation,
        #[schemars(with = "Value")]
        object: Value,
    },
    Apply {
        observation: Observation,
        expected: ObjectIdentity,
        field_manager: String,
        #[schemars(with = "Value")]
        object: Value,
    },
    Delete {
        observation: Observation,
        expected: ObjectIdentity,
    },
    CreateConflict {
        requested_name: String,
        refetched: Observation,
    },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct MutationPlanInputV0 {
    pub probe_version: String,
    pub qualification: BackendQualification,
    pub intent: MutationIntent,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(
    tag = "decision",
    rename_all = "camelCase",
    rename_all_fields = "camelCase",
    deny_unknown_fields
)]
pub enum MutationDecision {
    Post {
        method: HttpMethod,
        #[schemars(with = "Value")]
        body: Value,
    },
    ConditionalApply {
        method: HttpMethod,
        content_type: String,
        field_manager: String,
        force: bool,
        expected: ObjectIdentity,
        #[schemars(with = "Value")]
        body: Value,
    },
    PreconditionedDelete {
        method: HttpMethod,
        preconditions: ObjectIdentity,
    },
    RefetchNoAdopt {
        reason: String,
    },
    Conflict {
        reason: String,
    },
    Hold {
        reason: String,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub enum HttpMethod {
    #[serde(rename = "POST")]
    Post,
    #[serde(rename = "PATCH")]
    Patch,
    #[serde(rename = "DELETE")]
    Delete,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ProbeCaseV0 {
    pub name: String,
    pub input: MutationPlanInputV0,
    pub expected: MutationDecision,
}

#[derive(Debug, Error, PartialEq, Eq)]
pub enum MutationModelError {
    #[error("unsupported probe version `{0}`")]
    UnsupportedProbeVersion(String),
    #[error("invalid mutation model input: {0}")]
    InvalidInput(String),
}

/// Derive a side-effect-free mutation decision from one observed-state probe.
///
/// # Errors
///
/// Returns [`MutationModelError`] when the probe version is unsupported or the
/// requested identity and mutation body violate the model contract.
pub fn plan(input: &MutationPlanInputV0) -> Result<MutationDecision, MutationModelError> {
    if input.probe_version != PROBE_VERSION_V0 {
        return Err(MutationModelError::UnsupportedProbeVersion(
            input.probe_version.clone(),
        ));
    }

    if let BackendQualification::Unsupported { reason } = &input.qualification {
        return Ok(MutationDecision::Hold {
            reason: format!("backend/GVK is not qualified: {reason}"),
        });
    }

    match &input.intent {
        MutationIntent::Create {
            observation: Observation::Absent,
            object,
        } => {
            require_object(object)?;
            Ok(MutationDecision::Post {
                method: HttpMethod::Post,
                body: object.clone(),
            })
        }
        MutationIntent::Create {
            observation: Observation::Existing { .. },
            ..
        } => Ok(MutationDecision::RefetchNoAdopt {
            reason:
                "the requested physical identity already exists; implicit adoption is forbidden"
                    .into(),
        }),
        MutationIntent::CreateConflict { refetched, .. } => {
            let reason = match refetched {
                Observation::Absent => {
                    "POST returned a collision but refetch is absent; retry observation before planning"
                }
                Observation::Existing { .. } => {
                    "POST collided with an existing identity; refetch is recorded and adoption is forbidden"
                }
            };
            Ok(MutationDecision::RefetchNoAdopt {
                reason: reason.into(),
            })
        }
        MutationIntent::Apply {
            observation,
            expected,
            field_manager,
            object,
        } => {
            require_nonempty("fieldManager", field_manager)?;
            require_identity(expected)?;
            match require_matching_existing(observation, expected)? {
                IdentityMatch::Match => {
                    let body = object_with_identity(object, expected)?;
                    Ok(MutationDecision::ConditionalApply {
                        method: HttpMethod::Patch,
                        content_type: "application/apply-patch+yaml".into(),
                        field_manager: field_manager.clone(),
                        force: false,
                        expected: expected.clone(),
                        body,
                    })
                }
                IdentityMatch::UidCollision => Ok(MutationDecision::RefetchNoAdopt {
                    reason:
                        "observed UID differs from the expected identity; adoption is forbidden"
                            .into(),
                }),
                IdentityMatch::StaleResourceVersion => Ok(MutationDecision::Conflict {
                    reason: "observed resourceVersion differs from the expected version".into(),
                }),
                IdentityMatch::Absent => Ok(MutationDecision::Conflict {
                    reason: "expected object is absent".into(),
                }),
            }
        }
        MutationIntent::Delete {
            observation,
            expected,
        } => {
            require_identity(expected)?;
            match require_matching_existing(observation, expected)? {
                IdentityMatch::Match => Ok(MutationDecision::PreconditionedDelete {
                    method: HttpMethod::Delete,
                    preconditions: expected.clone(),
                }),
                IdentityMatch::UidCollision => Ok(MutationDecision::RefetchNoAdopt {
                    reason:
                        "observed UID differs from the expected identity; deletion is forbidden"
                            .into(),
                }),
                IdentityMatch::StaleResourceVersion => Ok(MutationDecision::Conflict {
                    reason: "observed resourceVersion differs from the expected version".into(),
                }),
                IdentityMatch::Absent => Ok(MutationDecision::Conflict {
                    reason: "expected object is already absent".into(),
                }),
            }
        }
    }
}

enum IdentityMatch {
    Match,
    UidCollision,
    StaleResourceVersion,
    Absent,
}

fn require_matching_existing(
    observation: &Observation,
    expected: &ObjectIdentity,
) -> Result<IdentityMatch, MutationModelError> {
    let Observation::Existing { identity } = observation else {
        return Ok(IdentityMatch::Absent);
    };
    require_identity(identity)?;
    if identity.uid != expected.uid {
        return Ok(IdentityMatch::UidCollision);
    }
    if identity.resource_version != expected.resource_version {
        return Ok(IdentityMatch::StaleResourceVersion);
    }
    Ok(IdentityMatch::Match)
}

fn object_with_identity(
    object: &Value,
    expected: &ObjectIdentity,
) -> Result<Value, MutationModelError> {
    let mut object = require_object(object)?.clone();
    let metadata = object
        .entry("metadata")
        .or_insert_with(|| Value::Object(Map::new()))
        .as_object_mut()
        .ok_or_else(|| {
            MutationModelError::InvalidInput("object.metadata must be an object".into())
        })?;

    reject_conflicting_metadata(metadata, "uid", &expected.uid)?;
    reject_conflicting_metadata(metadata, "resourceVersion", &expected.resource_version)?;
    metadata.insert("uid".into(), Value::String(expected.uid.clone()));
    metadata.insert(
        "resourceVersion".into(),
        Value::String(expected.resource_version.clone()),
    );
    Ok(Value::Object(object))
}

fn reject_conflicting_metadata(
    metadata: &Map<String, Value>,
    key: &str,
    expected: &str,
) -> Result<(), MutationModelError> {
    if let Some(actual) = metadata.get(key)
        && actual.as_str() != Some(expected)
    {
        return Err(MutationModelError::InvalidInput(format!(
            "object.metadata.{key} conflicts with the expected identity"
        )));
    }
    Ok(())
}

fn require_object(value: &Value) -> Result<&Map<String, Value>, MutationModelError> {
    let object = value.as_object().ok_or_else(|| {
        MutationModelError::InvalidInput("mutation body must be an object".into())
    })?;
    for field in ["apiVersion", "kind"] {
        let valid = object
            .get(field)
            .and_then(Value::as_str)
            .is_some_and(|value| !value.is_empty());
        if !valid {
            return Err(MutationModelError::InvalidInput(format!(
                "mutation body requires non-empty `{field}`"
            )));
        }
    }
    let name = object
        .get("metadata")
        .and_then(Value::as_object)
        .and_then(|metadata| metadata.get("name"))
        .and_then(Value::as_str)
        .unwrap_or_default();
    require_nonempty("metadata.name", name)?;
    Ok(object)
}

fn require_identity(identity: &ObjectIdentity) -> Result<(), MutationModelError> {
    require_nonempty("uid", &identity.uid)?;
    require_nonempty("resourceVersion", &identity.resource_version)
}

fn require_nonempty(field: &str, value: &str) -> Result<(), MutationModelError> {
    if value.is_empty() {
        return Err(MutationModelError::InvalidInput(format!(
            "{field} cannot be empty"
        )));
    }
    Ok(())
}
